-- News Collector V2 - G5 (US backfill) ROLLBACK, version 2. OPERATOR. Pure SQL: works in psql and in the Supabase SQL editor.
--
-- WHAT IT DOES (one transaction; any failed precondition or postcondition aborts and nothing is changed):
--   * deletes ONLY the ten G5 write-set entries of blizzard-bluepost-us (4 inserted, 6 updated) and all their version rows,
--     the tracked-topic row `topic:2360696` created by G5, and exactly ONE sync-run record: the G5 run id you supply;
--   * restores the six pre-G5 entries and their 16 version rows from the verified backup embedded in SECTION C.
--
-- PRECONDITIONS (the rollback REFUSES to run, changing nothing, if any of these is false):
--   P0 the three parameter tokens below were replaced (an unreplaced token is a syntax error on purpose);
--   P1 the run id is exactly one `mode = 'backfill'` run of blizzard-bluepost-us (other backfill/cron runs are never touched);
--   P2 all ten write-set entries exist and the current fingerprint (md5 of the full row text) of every one of them AND of every
--      one of their version rows equals the state captured right after the G5 apply (ops/news_v2_g5_capture.sql). A later
--      legitimate change (a revision edit, a new version, a manual edit) therefore blocks the rollback instead of being overwritten;
--   P3 topic 2360696 holds exactly the four G5 rows (a post ingested after G5, e.g. reply #10, blocks the rollback).
-- POSTCONDITIONS (checked before COMMIT; failure aborts the whole transaction):
--   the 22 restored rows match the pre-G5 fingerprints, the four inserted rows are gone, only the G5 run record was removed,
--   the suppressed-row fingerprint/count are unchanged, entries_total fell by exactly 4.
--
-- NOT RESTORED (see docs/web/news-collector-v2-g5-runbook.md section 8): news_sources freshness columns, news_verified_staff.last_seen_at,
--   news_tracked_topics of OTHER topics (last_checked_at / next_check_at / state / last_official_at), identity sequences (gaps remain),
--   cron sync runs that happened after G5, net._http_response rows, pg_stat counters, CDN/ISR caches of the website.
--
-- HOW TO USE
--   1. From the G5 apply response note `runId`. Right after the apply run ops/news_v2_g5_capture.sql and keep its output.
--   2. Replace the four tokens written between double angle brackets in the parameter block below: G5_RUN_ID (integer),
--      SUPPRESSED_MD5 (quoted) and SUPPRESSED_COUNT (both from the PRE-apply capture), POST_STATE_VALUES (the `post_state_values`
--      column of the POST-apply capture, verbatim).
--   3. psql: psql -v ON_ERROR_STOP=1 -f news_v2_g5_rollback.sql   (SQL editor: paste and run; an error aborts the batch).
begin;
set local role foreverdb_pub_owner;

create temp table g5_params on commit drop as
select <<G5_RUN_ID>>::bigint as run_id, <<SUPPRESSED_MD5>>::text as suppressed_md5, <<SUPPRESSED_COUNT>>::integer as suppressed_count;

create temp table g5_targets (source_entry_id text primary key) on commit drop;
insert into g5_targets values ('post:30185131'), ('post:30624529'), ('post:30634848'), ('post:30732723'),
    ('post:30743268'), ('post:30623027'), ('post:30638690'), ('post:30639364'), ('post:30640021'), ('post:30644593');

create temp table g5_expect_post (kind text not null, id bigint not null, h text not null) on commit drop;
insert into g5_expect_post (kind, id, h) values
<<POST_STATE_VALUES>>;

-- Pre-G5 fingerprints of the 6 entries + 16 versions in the backup (verified 22/22 against production on 2026-11-04).
create temp table g5_expect_pre (kind text not null, id bigint not null, h text not null) on commit drop;
insert into g5_expect_pre (kind, id, h) values
 ('entry', 32989, 'aabce4e690038bd20f07e19ef9441e81'), ('entry', 40722, 'c071c7ed00e02e5000340ed53f05a625'),
 ('entry', 40866, '6d456ec51ed349dbc0ca9b3e7e5b68b7'), ('entry', 40894, 'e253073c6023ff5cd74c86e1f97aa0e4'),
 ('entry', 41424, 'eb52336c57cc1a2273642c23462565d9'), ('entry', 88762, '3fc74114174d762667150d670ad2d6d0'),
 ('version', 2839, '29118fe2b85f302895f3d2253914ec49'), ('version', 2873, '2685451c50686554ec0db80fafe292b1'),
 ('version', 2876, 'a1dbb20e8ad166959f40ff619a1576e3'), ('version', 3083, '576fb4df45764eb2645968c7767b1987'),
 ('version', 3086, '517ce8fac2d7087dd17182603b5e0f5b'), ('version', 3087, 'bf6d381baca51b9668bf4a3c58957ec9'),
 ('version', 3091, '347cd5f370dd31f93d689334d3bf3814'), ('version', 3093, '3ad1c963fae75df32dedac59d3450188'),
 ('version', 3094, '74d6bb987977389418a772b6ba1b6dce'), ('version', 3095, 'd53910498bfd5ab1b7ea2c2a4d8f7198'),
 ('version', 3096, '1d6e9f9877b63356ff292c954644ea38'), ('version', 3702, '64f2f0935b7f8e0af6f4ebb11b5655c4'),
 ('version', 3716, '6c484e4289b78776511fada70c3fd207'), ('version', 4530, '69033a7a14f71fb35555b6a947880214'),
 ('version', 4532, '74ccd106d92bdcbd70cbd089d32311e2'), ('version', 4684, '13a64418a5e816816bb6b46f27ed54c8');

create temp table g5_ids on commit drop as
select e.id from pub.news_entries e join g5_targets t using (source_entry_id) where e.source_key = 'blizzard-bluepost-us';

create temp table g5_cur on commit drop as
select 'entry'::text as kind, e.id::bigint as id, md5(e::text) as h from pub.news_entries e where e.id in (select id from g5_ids)
union all
select 'version', v.id::bigint, md5(v::text) from pub.news_post_versions v where v.news_entry_id in (select id from g5_ids);

create temp table g5_state on commit drop as
select (select count(*) from pub.news_entries) as entries_before;

-- ---------------------------------------------------------------- SECTION A: preconditions (fail closed)
do $g5$
declare
    v_run bigint;
    v_n integer;
    v_diff integer;
begin
    select run_id into v_run from g5_params;
    if v_run is null or v_run <= 0 then
        raise exception 'G5 rollback precondition failed: the G5 run id is not set';
    end if;
    if (select count(*) from pub.news_sync_runs where id = v_run and mode = 'backfill' and source_key = 'blizzard-bluepost-us') <> 1 then
        raise exception 'G5 rollback precondition failed: run % is not a backfill run of blizzard-bluepost-us', v_run;
    end if;
    select count(*) into v_n from g5_ids;
    if v_n <> 10 then
        raise exception 'G5 rollback precondition failed: expected 10 write-set entries, found %', v_n;
    end if;
    if (select count(*) from pub.news_entries where source_key = 'blizzard-bluepost-us' and source_topic_id = 'topic:2360696') <> 4 then
        raise exception 'G5 rollback precondition failed: topic 2360696 holds rows other than the four G5 rows (a later post exists)';
    end if;
    select count(*) into v_diff from (
        (select kind, id, h from g5_cur except select kind, id, h from g5_expect_post)
        union all
        (select kind, id, h from g5_expect_post except select kind, id, h from g5_cur)) d;
    if v_diff <> 0 then
        raise exception 'G5 rollback precondition failed: % write-set row(s)/version(s) changed since the post-G5 capture; refusing to overwrite legitimate later changes', v_diff;
    end if;
end
$g5$;

-- ---------------------------------------------------------------- SECTION B: remove the G5 write set (scoped)
delete from pub.news_post_versions where news_entry_id in (select id from g5_ids);
delete from pub.news_entries where id in (select id from g5_ids);
delete from pub.news_tracked_topics where source_key = 'blizzard-bluepost-us' and topic_id = 'topic:2360696';
delete from pub.news_sync_runs where id = (select run_id from g5_params) and mode = 'backfill' and source_key = 'blizzard-bluepost-us';

-- ---------------------------------------------------------------- SECTION C: restore the verified pre-G5 backup (6 entries, 16 versions)
